WITH remaining_keys AS (SELECT country FROM suppliers EXCEPT SELECT country FROM suppliers WHERE rating >= 3.2), reconciled AS (SELECT s.* FROM suppliers s INNER JOIN remaining_keys k ON s.country = k.country) SELECT CASE WHEN rating >= 4.5 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, SIZE(COLLECT_SET(country)) AS num_countries, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, ROUND(AVG(rating), 2) AS avg_rating, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, COUNT(*) AS cnt FROM reconciled GROUP BY rating_tier ORDER BY avg_rating DESC;
